'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';

export interface PaginationProps extends React.HTMLAttributes<HTMLElement> {
  /** Current page number (1-based). */
  page: number;
  /** Total number of pages. */
  pageCount: number;
  /** Called with the new page number. */
  onPageChange?: (page: number) => void;
  /** How many page buttons to show around the current page (default 1). */
  siblings?: number;
}

/**
 * Numeric pagination with prev/next and ellipsis. Renders as a nav
 * landmark with aria-current="page" on the active button. Keyboard
 * users tab through buttons; each is a real <button> with a label.
 */
const Pagination = React.forwardRef<HTMLElement, PaginationProps>(
  ({ page, pageCount, onPageChange, siblings = 1, className, ...props }, ref) => {
    // Build the page number list with ellipsis markers.
    const pages: (number | 'ellipsis')[] = [];
    const start = Math.max(2, page - siblings);
    const end = Math.min(pageCount - 1, page + siblings);

    pages.push(1);
    if (start > 2) pages.push('ellipsis');
    for (let i = start; i <= end; i++) pages.push(i);
    if (end < pageCount - 1) pages.push('ellipsis');
    if (pageCount > 1) pages.push(pageCount);

    return (
      <nav
        ref={ref}
        aria-label="Pagination"
        className={cn('flex items-center justify-center gap-1', className)}
        {...props}
      >
        <button
          type="button"
          onClick={() => onPageChange?.(page - 1)}
          disabled={page <= 1}
          aria-label="Previous page"
          className={cn(
            'inline-flex h-8 items-center rounded-md border border-border px-2.5 text-sm transition-colors',
            'hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
            'disabled:pointer-events-none disabled:opacity-50'
          )}
        >
          ‹
        </button>
        {pages.map((entry, index) =>
          entry === 'ellipsis' ? (
            <span
              key={`ellipsis-${index}`}
              aria-hidden="true"
              className="px-2 text-sm text-muted-foreground"
            >
              …
            </span>
          ) : (
            <button
              key={entry}
              type="button"
              onClick={() => onPageChange?.(entry)}
              aria-current={entry === page ? 'page' : undefined}
              aria-label={`Page ${entry}`}
              className={cn(
                'inline-flex h-8 w-8 items-center justify-center rounded-md border text-sm transition-colors',
                'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                entry === page
                  ? 'border-primary bg-primary text-primary-foreground font-medium'
                  : 'border-border hover:bg-muted'
              )}
            >
              {entry}
            </button>
          )
        )}
        <button
          type="button"
          onClick={() => onPageChange?.(page + 1)}
          disabled={page >= pageCount}
          aria-label="Next page"
          className={cn(
            'inline-flex h-8 items-center rounded-md border border-border px-2.5 text-sm transition-colors',
            'hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
            'disabled:pointer-events-none disabled:opacity-50'
          )}
        >
          ›
        </button>
      </nav>
    );
  }
);
Pagination.displayName = 'Pagination';

export { Pagination };

{
  "id": "pagination",
  "name": "Pagination",
  "tier": "molecule",
  "description": "Numeric pagination with prev/next, ellipsis, and aria-current on the active page",
  "designIntent": "Pagination lets users navigate through paged content. It shows page numbers with ellipsis for large ranges, prev/next buttons, and marks the current page with aria-current=page.",
  "props": [
    { "name": "page", "type": "number", "required": true, "description": "Current page number (1-based)" },
    { "name": "pageCount", "type": "number", "required": true, "description": "Total number of pages" },
    { "name": "onPageChange", "type": "(page: number) => void", "required": false, "description": "Called with the new page number" },
    { "name": "siblings", "type": "number", "defaultValue": "1", "required": false, "description": "How many page buttons to show around the current page" },
    { "name": "className", "type": "string", "required": false, "description": "Additional CSS classes to apply" }
  ],
  "examples": [
    {
      "title": "Basic pagination",
      "code": "<Pagination page={3} pageCount={10} onPageChange={setPage} />",
      "description": "Navigate through 10 pages"
    },
    {
      "title": "Wide page range",
      "code": "<Pagination page={5} pageCount={20} siblings={2} onPageChange={setPage} />",
      "description": "Show more page buttons around the current page"
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use Pagination for infinite scroll content",
      "explanation": "Pagination implies discrete pages. Use a 'Load more' button or infinite scroll for continuous content."
    },
    {
      "title": "Don't hide the current page number",
      "explanation": "Users need to know where they are. Always show the active page with aria-current=page."
    }
  ],
  "accessibility": [
    { "feature": "Navigation landmark", "implementation": "nav[aria-label=Pagination]", "userRequirements": "Don't place multiple paginations on one page" },
    { "feature": "Current page", "implementation": "Active button has aria-current=page", "userRequirements": "Update aria-current when the page changes" },
    { "feature": "Disabled buttons", "implementation": "Prev/next are disabled at the boundaries", "userRequirements": "Disabled buttons are removed from tab order" }
  ],
  "contentGuidelines": [
    { "contentType": "Labels", "guidelines": ["Use aria-label for prev/next buttons", "Page numbers are self-explanatory"], "goodExamples": ["Previous page", "Next page", "Page 3"], "badExamples": ["<", ">", "..."] }
  ],
  "compositionRules": [
    { "component": "Table", "relationship": "Paginate long table data", "example": "<Table>...</Table><Pagination page={page} pageCount={total} onPageChange={setPage} />" }
  ],
  "relatedComponents": ["Table", "Breadcrumb"],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.1.0",
  "sourceDir": "pagination",
  "exportName": "Pagination"
}
